const s = load("pr569_review_snapshot");
const clean = (body) => {
  let x = body ?? "";
  x = x.split("<details>")[0];
  x = x.split("Useful?")[0];
  x = x.replace(/<!--[\s\S]*?-->/g, "").trim();
  return x.slice(0, 2400);
};
const unresolved = s.threads.filter(t => !t.isResolved).map((t, i) => ({
  n:i+1,
  id:t.id,
  path:t.path,
  comments:t.comments.nodes.map(c => ({
    author:c.author?.login,
    createdAt:c.createdAt,
    outdated:c.outdated,
    line:c.line,
    url:c.url,
    body:clean(c.body)
  }))
}));
const reviews = s.reviews.filter(r => r.body?.trim()).map((r,i) => ({
  n:i+1,
  author:r.author?.login,
  state:r.state,
  submittedAt:r.submittedAt,
  body:clean(r.body)
}));
text(JSON.stringify({unresolved,reviews}, null, 2));

