deployWorkflow
name: Account Service Deploy

permissions:
  contents: read

on:
  push:
    branches:
      - dev
    tags:
      - backend-pre-*
      - backend-live-*
  workflow_dispatch:
    inputs:
      environment:
        description: Account environment to deploy
        required: true
        type: choice
        default: dev
        options:
          - dev
          - pre
          - live
      regions:
        description: Comma-separated regions
        required: false
        default: insouth,useast,euwest

jobs:
  detect:
    runs-on: ubuntu-latest
    outputs:
      environment: ${{ steps.detect.outputs.environment }}
      regions: ${{ steps.detect.outputs.regions }}
    steps:
      - id: detect
        env:
          EVENT_NAME: ${{ github.event_name }}
          INPUT_ENVIRONMENT: ${{ github.event.inputs.environment }}
          INPUT_REGIONS: ${{ github.event.inputs.regions }}
          REF_TYPE: ${{ github.ref_type }}
        run: |
          set -euo pipefail

          default_regions="insouth,useast,euwest"
          if [ "$EVENT_NAME" = "workflow_dispatch" ]; then
            environment="${INPUT_ENVIRONMENT:-dev}"
            regions="${INPUT_REGIONS:-$default_regions}"
            case "$environment" in
              pre)
                [[ "$REF_TYPE" == "tag" && "${GITHUB_REF_NAME}" == backend-pre-* ]] || {
                  echo "Pre deploys must run from a backend-pre-* tag" >&2
                  exit 1
                }
                ;;
              live)
                [[ "$REF_TYPE" == "tag" && "${GITHUB_REF_NAME}" == backend-live-* ]] || {
                  echo "Live deploys must run from a backend-live-* tag" >&2
                  exit 1
                }
                ;;
            esac
          elif [[ "$REF_TYPE" == "tag" && "${GITHUB_REF_NAME}" == backend-pre-* ]]; then
            environment="pre"
            regions="$default_regions"
          elif [[ "$REF_TYPE" == "tag" && "${GITHUB_REF_NAME}" == backend-live-* ]]; then
            environment="live"
            regions="$default_regions"
          else
            environment="dev"
            regions="$default_regions"
          fi

          case "$environment" in
            dev|pre|live) ;;
            *) echo "Invalid environment: $environment" >&2; exit 1 ;;
          esac

          sanitized_regions=""
          IFS=',' read -ra requested_regions <<< "$regions"
          for region in "${requested_regions[@]}"; do
            region="$(echo "$region" | xargs)"
            case "$region" in
              insouth|useast|euwest) ;;
              *) echo "Invalid region: $region" >&2; exit 1 ;;
            esac
            if [ -z "$sanitized_regions" ]; then
              sanitized_regions="$region"
            else
              sanitized_regions="$sanitized_regions,$region"
            fi
          done

          if [ -z "$sanitized_regions" ]; then
            echo "At least one region is required" >&2
            exit 1
          fi

          echo "environment=$environment" >> "$GITHUB_OUTPUT"
          echo "regions=$sanitized_regions" >> "$GITHUB_OUTPUT"

  deploy:
    runs-on: ubuntu-latest
    needs: detect
    concurrency:
      group: account-service-deploy-${{ needs.detect.outputs.environment }}
      cancel-in-progress: false
    environment: ${{ needs.detect.outputs.environment }}
    permissions:
      contents: read
    steps:
      - name: Checkout Nucleus
        uses: actions/checkout@v4

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 22
          cache: npm

      - name: Install dependencies
        run: npm install --legacy-peer-deps

      - name: Account service typecheck
        run: npm --workspace @21n/account-service run typecheck

      - name: Account service E2E memory
        run: npm --workspace @21n/account-service run test:e2e:apifn:memory

      - name: Deploy account service
        env:
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          TODO_LIVE_INSOUTH_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_INSOUTH_HYPERDRIVE_ID }}
          TODO_LIVE_USEAST_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_USEAST_HYPERDRIVE_ID }}
          TODO_LIVE_EUWEST_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_EUWEST_HYPERDRIVE_ID }}
          TODO_LIVE_INSOUTH_SYNC_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_INSOUTH_SYNC_HYPERDRIVE_ID }}
          TODO_LIVE_USEAST_SYNC_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_USEAST_SYNC_HYPERDRIVE_ID }}
          TODO_LIVE_EUWEST_SYNC_HYPERDRIVE_ID: ${{ vars.TODO_LIVE_EUWEST_SYNC_HYPERDRIVE_ID }}
        run: npm --workspace @21n/account-service run deploy:${{ needs.detect.outputs.environment }} -- --regions=${{ needs.detect.outputs.regions }}

