const rs = [];
for (const cmd of [
  "PATH=/opt/homebrew/opt/node@22/bin:$PATH npm --workspace @21n/account-service run test:e2e:apifn:multiregion",
  "PATH=/opt/homebrew/opt/node@22/bin:$PATH npm --workspace @21n/account-service run test:e2e:apifn:ratelimit"
]) {
  rs.push(await tools.exec_command({
    cmd,
    workdir:"/Users/serro/Documents/dev/n/nucleus-pr-569-review",
    yield_time_ms:30000,
    max_output_tokens:30000
  }));
}
rs.forEach((r,i)=>{text(`RESULT ${i+1}\nexit=${r.exit_code}\n${r.output}`); if(r.session_id)text(`SESSION_${i+1}=${r.session_id}`)});

const r = await tools.exec_command({
  cmd: "DATAFN_DATABASE_URL='REDACTED' npm run datafn:migrate",
  workdir: "/Users/serro/Documents/dev/n/nucleus-pr-569-review/services/account",
  yield_time_ms: 10000,
  max_output_tokens: 8000
});
text(JSON.stringify({exit_code:r.exit_code,output:r.output}, null, 2));

const r = await tools.exec_command({
  cmd: "sed -n '1,240p' services/account/src/testing/run-apifn-ratelimit.ts; sed -n '1,260p' services/account/src/testing/harness.ts; rg -n \"securityEvent|createAccountSecurityAuditSink|eventSink|rate_limited\" services/account/src/testing services/account/src",
  workdir: "/Users/serro/Documents/dev/n/nucleus-pr-569-review",
  yield_time_ms: 10000,
  max_output_tokens: 30000
});
text(r.output);

