const code = `
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import {
  AuthFnRegionLookupDurableObject,
  createCloudflareRegionLookupStore
} from "@authfn/lookup-cloudflare-do";
import { createDynamoDbRegionLookupStore } from "@authfn/lookup-dynamodb";

const identifier = "legacy@example.test";
const record = {
  identifier,
  userId: "user:legacy",
  regionId: "insouth",
  authority: "https://account-insouth.nucleum.app",
  createdAt: "2026-01-01T00:00:00.000Z",
  updatedAt: "2026-01-01T00:00:00.000Z"
};
const prefix = "nucleus_account:";
const oldObjectName = prefix + createHash("sha256").update(identifier).digest("hex");
const states = new Map();
const stateFor = (name) => {
  if (!states.has(name)) {
    const entries = new Map(name === oldObjectName ? [["record", record]] : []);
    states.set(name, {
      storage: {
        get: async (key) => entries.get(key),
        put: async (key, value) => void entries.set(key, value),
        delete: async (key) => entries.delete(key)
      }
    });
  }
  return states.get(name);
};
const namespace = {
  idFromName: (name) => name,
  get: (name) => ({
    fetch: (input, init) => new AuthFnRegionLookupDurableObject(stateFor(name)).fetch(new Request(input, init))
  })
};
const cloudflare = createCloudflareRegionLookupStore(namespace, { objectNamePrefix: prefix });
assert.deepEqual(JSON.parse(await cloudflare.get(identifier)), record);
const currentKey = "authfn:region:" + identifier;
assert.deepEqual(await cloudflare.setIfAbsent({ key: currentKey, value: JSON.stringify(record) }), { inserted: true });
assert.deepEqual(JSON.parse(await cloudflare.get(currentKey)), record);

const dynamo = createDynamoDbRegionLookupStore({
  tableName: "lookup",
  documentClient: {
    send: async () => ({ Item: { PK: identifier, SK: "LOOKUP", ...record } })
  }
});
assert.deepEqual(JSON.parse(await dynamo.get(identifier)), record);
process.stdout.write("lookup-migration-probe=pass\\n");
`;
const escaped = code.replace(/'/g, "'\\''");
const r = await tools.exec_command({
  cmd: `PATH=/opt/homebrew/opt/node@22/bin:$PATH node --input-type=module -e '${escaped}'`,
  workdir: "/Users/serro/Documents/dev/n/nucleus-pr-569-review/services/account",
  yield_time_ms: 10000,
  max_output_tokens: 8000
});
text(r.output);

