/** Cloudflare bindings and environment values available to the account Worker. */
export interface AccountWorkerEnv {
  ACCOUNT_DB?: {
    connectionString: string;
  };
  SYNC_DB?: {
    connectionString: string;
  };
  ACCOUNT_CACHE?: KVNamespace;
  AUTHFN_REGION_LOOKUP?: DurableObjectNamespace;
  ACCOUNT_RUNTIME_STORES?: DurableObjectNamespace;
  DATABASE_URL?: string;
  DATAFN_DATABASE_URL?: string;
  [key: string]: unknown;
}

/** Cloudflare Secrets Store binding exposed to the Worker runtime. */
export interface CloudflareSecretsStoreBinding {
  get(): Promise<string>;
  [key: string]: unknown;
}
import { defineConfig } from "drizzle-kit";
import { requireSecureRemotePostgresUrl } from "./src/db/postgres-security.js";

const databaseUrl = process.env.DATAFN_DATABASE_URL?.trim();
if (!databaseUrl) {
  throw new Error("DATAFN_DATABASE_URL is required for DataFn migrations");
}
requireSecureRemotePostgresUrl(databaseUrl);

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/generated/datafn/datafn-schema.drizzle.ts",
  out: "./drizzle/datafn",
  dbCredentials: {
    url: databaseUrl
  }
});
